}
/** A named test declaration: `it`/`test` (any modifier chain) with a string name. */
function isNamedTestCall(node) {
    const root = rootCallName(node.callee);
    if (root !== "it" && root !== "test") {
        return false;
    }
    const first = node.arguments[0];
