    if (isLinked(corpus.entry, startLine, node.loc.end.line)) {
        return;
    }
    context.report({
        node: node.callee,
        messageId: "unlinkedTest",
        data: {
            name: testName(context.sourceCode, node.arguments[0]),
            file: corpus.relPath,
            line: String(startLine),
