101	        },
102	        heading: (_lines, i, line) => {
103	            this.flushParagraph();
104	            this.currentHeading = parseHeading(line);
105	            return i;
106	        },
107	        table: (_lines, i) => {
108	            this.flushParagraph();
109	            return i;
110	        },
111	        "list-item": (lines, i) => {
112	            this.flushParagraph();
